def entregas_a_citas(apps, schema_editor):
    Proyecto = apps.get_model('gestion', 'Proyecto')
    Cita = apps.get_model('gestion', 'Cita')
    for proyecto in Proyecto.objects.exclude(fecha_entrega=None):
        Cita.objects.create(proyecto=proyecto, fecha=proyecto.fecha_entrega, motivo='Entrega')


def citas_a_entregas(apps, schema_editor):
    # Al deshacer: la primera cita de cada proyecto vuelve a ser su fecha de entrega
    Proyecto = apps.get_model('gestion', 'Proyecto')
    for proyecto in Proyecto.objects.all():
        cita = proyecto.citas.order_by('fecha').first()
        if cita:
            proyecto.fecha_entrega = cita.fecha
            proyecto.save(update_fields=['fecha_entrega'])


